arguments.file_text:
export function initScrollObserver(messageListElement, dotNetRef) {
    if (!messageListElement) return;

    messageListElement.addEventListener('scroll', () => {
        if (messageListElement.scrollTop === 0) {
            dotNetRef.invokeMethodAsync('LoadOlderMessages');
        }
    });
}

export function scrollToBottom(element) {
    if (element) {
        element.scrollTop = element.scrollHeight;
    }
}

