public class StubChatService : IChatService
{
    private readonly List<Channel> _channels =
    [
        new(1, "general", "General discussion for the team", 3),
        new(2, "engineering", "Engineering updates and technical discussions", 0),
        new(3, "design", "Design reviews, feedback, and assets", 1),
        new(4, "random", "Off-topic conversations and fun", 5),
    ];

    private readonly List<Message> _messages;
    private int _nextMessageId = 100;

    public StubChatService()
    {
        _messages =
        [
            new(1, 1, "Alice", "Hey everyone! Welcome to the new chat app.", DateTime.UtcNow.AddHours(-3), null, [new("👍", ["Bob", "Charlie"])]),
            new(2, 1, "Bob", "Looks great! Love the new design.", DateTime.UtcNow.AddHours(-2), null, [new("❤️", ["Alice"])]),
            new(3, 1, "Charlie", "Thanks for setting this up. Quick question about the channels.", DateTime.UtcNow.AddMinutes(-90), null, []),
            new(4, 1, "Alice", "Sure! Each channel is topic-specific. Feel free to create new ones.", DateTime.UtcNow.AddMinutes(-85), 3, []),
            new(5, 1, "Dave", "Can we get a #devops channel?", DateTime.UtcNow.AddMinutes(-30), null, [new("🎉", ["Alice", "Bob"])]),
            new(6, 1, "Alice", "Absolutely, I'll set one up now.", DateTime.UtcNow.AddMinutes(-25), 5, []),
            new(7, 2, "Bob", "Deployed v2.1 to staging. Please test!", DateTime.UtcNow.AddHours(-1), null, [new("👀", ["Charlie", "Dave"])]),
            new(8, 2, "Charlie", "On it. Will report back in 30 min.", DateTime.UtcNow.AddMinutes(-50), 7, []),
            new(9, 3, "Dave", "New mockups are in Figma. Link in the description.", DateTime.UtcNow.AddMinutes(-120), null, []),
        ];
    }

    public Task<List<Channel>> GetChannelsAsync() =>
        Task.FromResult(_channels.ToList());

    public Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take) =>
        Task.FromResult(
            _messages.Where(m => m.ChannelId == channelId && m.ReplyToId == null)
                     .OrderBy(m => m.SentAt)
                     .Skip(skip)
                     .Take(take)
                     .ToList());

    public Task<Message> SendMessageAsync(int channelId, string content, int? replyToId)
    {
        var msg = new Message(
            Interlocked.Increment(ref _nextMessageId),
            channelId,
            "You",
            content,
            DateTime.UtcNow,
            replyToId,
            []);
        _messages.Add(msg);
        return Task.FromResult(msg);
    }

    public Task<List<Message>> GetThreadAsync(int rootMessageId) =>
        Task.FromResult(
            _messages.Where(m => m.ReplyToId == rootMessageId)
                     .OrderBy(m => m.SentAt)
                     .ToList());

    public Task AddReactionAsync(int messageId, string emoji)
    {
        var msg = _messages.FirstOrDefault(m => m.Id == messageId);
        if (msg is not null)
        {
            var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == emoji);
            if (existing is not null)
            {
                if (!existing.Users.Contains("You"))
                    existing.Users.Add("You");
            }
            else
            {
                msg.Reactions.Add(new Reaction(emoji, ["You"]));
            }
        }
        return Task.CompletedTask;
    }

    public Task MarkChannelReadAsync(int channelId)
    {
        var idx = _channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            _channels[idx] = _channels[idx] with { UnreadCount = 0 };
        }
        return Task.CompletedTask;
    }
}

